#!/usr/bin/env bash
# Antioch Framework - Portable Installer
# Single-command installation: curl -sSL <url> | bash
# Or download and run: bash antioch-installer.sh

set -e

INSTALL_DIR="${HOME}/.antioch"
BIN_DIR="${HOME}/.local/bin"
ANTIOCH_VERSION="0.1.0"
FROM_GITHUB=false
GITHUB_REPO="https://github.com/nielrya4/antioch.git"
GITHUB_BRANCH="master"

# Colors for output
RED='\033[0;31m'
GREEN='\033[0;32m'
YELLOW='\033[1;33m'
BLUE='\033[0;34m'
NC='\033[0m' # No Color

print_header() {
    echo -e "${BLUE}"
    echo "╔════════════════════════════════════════════════════════════════╗"
    echo "║                                                                ║"
    echo "║                    Antioch Framework                           ║"
    echo "║                  Portable Installer v${ANTIOCH_VERSION}                    ║"
    echo "║                                                                ║"
    echo "╚════════════════════════════════════════════════════════════════╝"
    echo -e "${NC}"
}

print_step() {
    echo -e "${GREEN}▶${NC} $1"
}

print_warning() {
    echo -e "${YELLOW}⚠${NC} $1"
}

print_error() {
    echo -e "${RED}✗${NC} $1"
}

print_success() {
    echo -e "${GREEN}✓${NC} $1"
}

# Parse command line arguments
UNINSTALL=false
SYSTEM_WIDE=false

while [[ $# -gt 0 ]]; do
    case $1 in
        --uninstall)
            UNINSTALL=true
            shift
            ;;
        --system)
            SYSTEM_WIDE=true
            INSTALL_DIR="/opt/antioch"
            BIN_DIR="/usr/local/bin"
            shift
            ;;
        --from-github)
            FROM_GITHUB=true
            shift
            ;;
        --repo)
            GITHUB_REPO="$2"
            shift 2
            ;;
        --branch)
            GITHUB_BRANCH="$2"
            shift 2
            ;;
        --help|-h)
            echo "Antioch Framework Installer"
            echo ""
            echo "Usage: $0 [OPTIONS]"
            echo ""
            echo "Options:"
            echo "  --system        Install system-wide (requires sudo, installs to /opt/antioch)"
            echo "  --from-github   Install from GitHub instead of embedded archive"
            echo "  --repo URL      Specify GitHub repository URL (use with --from-github)"
            echo "  --branch NAME   Specify branch to install (use with --from-github, default: master)"
            echo "  --uninstall     Uninstall Antioch"
            echo "  --help, -h      Show this help message"
            echo ""
            echo "Default: Installs to ~/.antioch from embedded archive"
            echo ""
            echo "Examples:"
            echo "  $0                              # Install from embedded archive"
            echo "  $0 --from-github                # Install from GitHub master branch"
            echo "  $0 --from-github --branch dev   # Install from GitHub dev branch"
            exit 0
            ;;
        *)
            print_error "Unknown option: $1"
            echo "Use --help for usage information"
            exit 1
            ;;
    esac
done

# Uninstall
if [ "$UNINSTALL" = true ]; then
    print_header
    echo "Uninstalling Antioch..."
    echo ""

    if [ "$SYSTEM_WIDE" = true ] && [ "$EUID" -ne 0 ]; then
        print_error "System-wide uninstall requires sudo"
        echo "Run: sudo $0 --system --uninstall"
        exit 1
    fi

    if [ -d "$INSTALL_DIR" ]; then
        print_step "Removing $INSTALL_DIR"
        rm -rf "$INSTALL_DIR"
        print_success "Removed installation directory"
    fi

    if [ -f "$BIN_DIR/antioch" ]; then
        print_step "Removing $BIN_DIR/antioch"
        rm -f "$BIN_DIR/antioch"
        print_success "Removed antioch command"
    fi

    echo ""
    print_success "Antioch has been uninstalled"
    exit 0
fi

# Check for sudo if system-wide
if [ "$SYSTEM_WIDE" = true ] && [ "$EUID" -ne 0 ]; then
    print_error "System-wide installation requires sudo"
    echo "Run: sudo $0 --system"
    exit 1
fi

print_header

# Check Python version
print_step "Checking Python installation..."
if ! command -v python3 &> /dev/null; then
    print_error "Python 3 is not installed"
    echo "Please install Python 3.9 or higher"
    exit 1
fi

PYTHON_VERSION=$(python3 -c 'import sys; print(".".join(map(str, sys.version_info[:2])))')
print_success "Found Python $PYTHON_VERSION"

# Check minimum version (3.9)
PYTHON_MAJOR=$(python3 -c 'import sys; print(sys.version_info[0])')
PYTHON_MINOR=$(python3 -c 'import sys; print(sys.version_info[1])')

if [ "$PYTHON_MAJOR" -lt 3 ] || ([ "$PYTHON_MAJOR" -eq 3 ] && [ "$PYTHON_MINOR" -lt 9 ]); then
    print_error "Python 3.9 or higher is required (found $PYTHON_VERSION)"
    exit 1
fi

# Create installation directory
print_step "Creating installation directory: $INSTALL_DIR"
mkdir -p "$INSTALL_DIR"
print_success "Created $INSTALL_DIR"

# Install from GitHub or embedded archive
if [ "$FROM_GITHUB" = true ]; then
    # Check for git
    if ! command -v git &> /dev/null; then
        print_error "Git is not installed (required for --from-github)"
        echo "Please install git or remove --from-github flag"
        exit 1
    fi

    print_step "Cloning from GitHub: $GITHUB_REPO (branch: $GITHUB_BRANCH)"

    # Create temp directory for clone
    TEMP_CLONE=$(mktemp -d)

    # Clone the repository
    git clone --depth 1 --branch "$GITHUB_BRANCH" "$GITHUB_REPO" "$TEMP_CLONE" 2>&1 | grep -v "Cloning into" || true

    # Copy only the antioch framework library from GitHub
    print_step "  → Copying antioch framework from GitHub"
    cp -r "$TEMP_CLONE/antioch" "$INSTALL_DIR/"

    # Extract CLI and build tools from embedded archive
    print_step "  → Extracting CLI and build tools from installer"
    ARCHIVE_LINE=$(awk '/^__ARCHIVE_BELOW__/ {print NR + 1; exit 0; }' "$0")
    tail -n+${ARCHIVE_LINE} "$0" | base64 -d | tar -xzf - -C "$INSTALL_DIR" --strip-components=1 \
        antioch-build/cli.py \
        antioch-build/environment.py \
        antioch-build/build.py \
        antioch-build/antioch.toml \
        2>/dev/null || true

    # Create minimal scripts folder with example main.py
    print_step "  → Creating example scripts"
    mkdir -p "$INSTALL_DIR/scripts"
    cat > "$INSTALL_DIR/scripts/main.py" << 'EXAMPLE_MAIN'
"""
Example Antioch Application
Edit this file to build your app!
"""
from antioch import *

def main():
    # Create a simple example
    DOM.add(
        H1("Welcome to Antioch!", style={
            "color": "#2196F3",
            "text-align": "center",
            "margin-top": "50px"
        })
    )

    DOM.add(
        P("Edit scripts/main.py to start building your application.", style={
            "text-align": "center",
            "color": "#666"
        })
    )

    # Simple interactive example
    counter = 0
    display = H2(f"Count: {counter}", style={"text-align": "center"})
    DOM.add(display)

    button = Button("Click Me!", style={
        "display": "block",
        "margin": "20px auto",
        "padding": "10px 20px",
        "font-size": "16px",
        "background-color": "#4CAF50",
        "color": "white",
        "border": "none",
        "border-radius": "4px",
        "cursor": "pointer"
    })
    DOM.add(button)

    @when(button.events.click)
    def increment(sender, event):
        nonlocal counter
        counter += 1
        display.set_text(f"Count: {counter}")

if __name__ == "__main__":
    main()
EXAMPLE_MAIN

    # Create assets folder
    mkdir -p "$INSTALL_DIR/assets"

    # Cleanup
    rm -rf "$TEMP_CLONE"

    print_success "Installed from GitHub ($GITHUB_BRANCH branch)"
else
    # Extract from embedded archive
    print_step "Extracting Antioch framework..."
    ARCHIVE_LINE=$(awk '/^__ARCHIVE_BELOW__/ {print NR + 1; exit 0; }' "$0")
    tail -n+${ARCHIVE_LINE} "$0" | base64 -d | tar -xzf - -C "$INSTALL_DIR" --strip-components=1
    print_success "Extracted framework files"
fi

# Create bin directory
print_step "Setting up antioch command..."
mkdir -p "$BIN_DIR"

# Create the antioch executable
cat > "$BIN_DIR/antioch" << EXEC_EOF
#!/usr/bin/env bash
# Antioch CLI - Installed executable

# Add antioch install dir to Python path so CLI can import environment
export PYTHONPATH="$INSTALL_DIR:\$PYTHONPATH"

# Run CLI in current directory (not install directory)
python3 "$INSTALL_DIR/cli.py" "\$@"
EXEC_EOF

chmod +x "$BIN_DIR/antioch"
print_success "Created antioch command at $BIN_DIR/antioch"

# Check if bin dir is in PATH
echo ""
if [[ ":$PATH:" != *":$BIN_DIR:"* ]]; then
    print_warning "$BIN_DIR is not in your PATH"
    echo ""
    echo "Add it by adding this line to your ~/.bashrc or ~/.zshrc:"
    echo ""
    echo "    export PATH=\"$BIN_DIR:\$PATH\""
    echo ""
    echo "Then reload your shell: source ~/.bashrc"
else
    print_success "$BIN_DIR is already in your PATH"
fi

# Installation complete
echo ""
echo -e "${GREEN}╔════════════════════════════════════════════════════════════════╗${NC}"
echo -e "${GREEN}║                                                                ║${NC}"
echo -e "${GREEN}║         ✓ Antioch Framework installed successfully!            ║${NC}"
echo -e "${GREEN}║                                                                ║${NC}"
echo -e "${GREEN}╚════════════════════════════════════════════════════════════════╝${NC}"
echo ""
echo "Installation location: $INSTALL_DIR"
echo "Executable: $BIN_DIR/antioch"
echo ""
echo "Quick Start:"
echo "  1. Create a new project directory"
echo "  2. Run: antioch build"
echo "  3. Run: antioch run"
echo ""
echo "Documentation: $INSTALL_DIR/README_CLI.md"
echo ""
echo "To uninstall: $0 --uninstall"
echo ""

exit 0

__ARCHIVE_BELOW__
